package br.com.sol7.olimpio.basico.tipoagenda.controller;
import br.com.sol7.olimpio.shared.PagedResponse;
import io.smallrye.mutiny.Uni; import jakarta.inject.Inject; import jakarta.validation.Valid; import jakarta.ws.rs.*; import jakarta.ws.rs.core.*; import java.util.List;
import br.com.sol7.olimpio.basico.tipoagenda.dto.TipoAgendaRequest;
import br.com.sol7.olimpio.basico.tipoagenda.dto.TipoAgendaResponse;
import br.com.sol7.olimpio.basico.tipoagenda.service.TipoAgendaService;
@Path("/api/basico/tipo-agenda") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON) public class TipoAgendaController { @Inject TipoAgendaService service; @GET public Uni<List<TipoAgendaResponse>> list(){return service.list();} @GET @Path("/paged") public Uni<PagedResponse<TipoAgendaResponse>> paged(@QueryParam("page") Integer page,@QueryParam("size") Integer size){return service.paged(page==null?0:page,size==null?10:size);} @GET @Path("/{id}") public Uni<TipoAgendaResponse> find(@PathParam("id") Long id){return service.find(id);}@POST public Uni<Response> create(@Valid TipoAgendaRequest r){return service.create(r).map(item->Response.status(Response.Status.CREATED).entity(item).build());}@PUT @Path("/{id}") public Uni<TipoAgendaResponse> update(@PathParam("id") Long id,@Valid TipoAgendaRequest r){return service.update(id,r);}@DELETE @Path("/{id}") public Uni<Void> delete(@PathParam("id") Long id){return service.delete(id);} }